USE test GO

-- drop Restaurant database if it already exists
IF DB_ID('Rest') IS NOT NULL DROP database Rest GO

CREATE database Rest GO
USE Rest GO

-- create Login tables 
CREATE table User ( 
    userID varchar(8) NOT NULL, 
    password varchar(20) NOT NULL, 
    -- hash is generated by computer
    authLevel enum('Staff','Manager','Owner') NOT NULL, 
    firstName varchar(30),
    lastName varchar(30),
    storeID varchar(8),
    Primary key(userID),
    Foreign key (storeID) references Store 
);

-- create Recipe
CREATE table Recipe (
    recipeID varchar(8) NOT NULL,
    recipeName varchar(64),
    Primary key (recipeID),
);

-- create Menu tables 
CREATE table Menu (
    menuID varchar(8) NOT NULL,
    category enum('Breakfast','Lunch','Dinner','Dessert','Appetizer','Drinks','Sides','Special','Seasonal'),
    servingSize varchar(64),
    Primary key (menuID)
);

-- create MenuDescription
CREATE table MenuDescription (
    menuID varchar(8) NOT NULL,
    recipeID varchar (8) NOT NULL,
    menuName varchar(64),
    menuPrice decimal(10,2),
    allergyInfo varchar(64),
    Foreign key (menuID) references Menu(menuID),
    Foreign key (recipeID) references Recipe(recipeID)
);


-- create Inventory tables 
CREATE table Item (
    itemID varchar(8) NOT NULL,
    itemName varchar(64) NOT NULL,
    allergyInfo varchar(64),
    Primary key(itemID)
);

CREATE table Inventory (
    itemID varchar(8) NOT NULL,
    storeID varchar(8) NOT NULL,
    quantity numeric(8,2) CHECK (quantity >= 0),
    Primary key (itemID),
    Foreign key (itemID) references Item(itemID)
);


-- create Info tables 
CREATE table Store (
    storeID varchar(8) NOT NULL,
    address varchar(100),
    hours varchar(64),
    phone integer(10),
    storeEmail varchar(50),
    Primary key(storeID)
);

-- create Event tables
/* added e in front to avoid datatype look alike */

CREATE table Event (
    eventID varchar(8) NOT NULL,
    eventName varchar(64) NOT NULL,
    eDate date,
    eTime time, 
    category varchar(64),
    storeID varchar(8),
    PRIMARY KEY(eventID),
    FOREIGN KEY (storeID) REFERENCES Store(storeID)
);

CREATE table EventDescription (
    eventID varchar(8) NOT NULL,
    description TEXT,
    eventName varchar(64) NOT NULL,
    eLocation varchar(64),
    PRIMARY KEY(eventID),
    FOREIGN KEY (eventID) REFERENCES Event(eventID)
)

-- create Inquiry
CREATE table Inquiry(
    inquiryID varchar(8) NOT NULL,
    iTime time,
    iDate date,
    storeID varchar(8) NOT NULL,
    PRIMARY KEY(inquiryID),
    FOREIGN KEY (storeID) REFERENCES Store(storeID)
)

CREATE table InquiryDescription(
    inquiryID varchar(8) NOT NULL,
    phoneNumber integer(10) NOT NULL,
    firstName varchar(30) NOT NULL,
    lastName varchar(30) NOT NULL,
    IEmail varchar(50) NOT NULL,
    description TEXT,
    PRIMARY KEY(inquiryID),
    FOREIGN KEY (inquiryID) REFERENCES Inquiry(inquiryID)
)


-- weak entity sets
CREATE table StoreStaff(
    userID varchar(8) NOT NULL,
    storeID varchar(8) NOT NULL,
    Foreign KEY(userID) REFERENCES User(userID),
    Foreign Key(storeID) REFERENCES Store(storeID)
)

CREATE table EventItems (
        eventID varchar(8) NOT NULL,
        itemID varchar(8) NOT NULL,
        quantityNeeded int,
        FOREIGN KEY (eventID) REFERENCES Event(eventID),
        FOREIGN KEY (itemID) REFERENCES Item(itemID)
)

-- create MenuItem
CREATE table MenuItem (
    menuID varchar(8) NOT NULL,
    itemID varchar(8) NOT NULL,
    Foreign key (menuID) references Menu(menuID)
);



-- create RecipeIngredients
CREATE table RecipeIngredients (
    recipeID varchar(8) NOT NULL,
    itemID varchar(8) NOT NULL,
    Foreign key (recipeID) references Recipe(recipeID),
    Foreign Key (itemID) REFERENCES Item(itemID)
);